1	/**
2	 * @file gpx_ext_sensor.c
3	 * @brief 传感器 GPX 扩展实现：心率 / 踏频 / 速度（gpxtpx v2）+ 功率（gpxpx）。
4	 *
5	 * SPDX-License-Identifier: Apache-2.0
6	 */
