18	#define GPX_SENSOR_NS_GPXTPX \
19	  "http://www.garmin.com/xmlschemas/TrackPointExtension/v2"
20	#define GPX_SENSOR_NS_POWER \
21	  "http://www.garmin.com/xmlschemas/PowerExtension/v1"
22	
23	/* 两个外层标签各自带命名空间声明，只写一次；下面的字段都是纯元素。
24	 * 单独做成常量而不是把 XML 直接拼进 format：format 串跨行拼接会被安全扫描
25	 * 判成隐患（本文件曾经就是这个写法）。
26	 *
27	 * 用 v2 而不是 v1：gpxtpx:speed 只在 v2 里定义。
28	 */
29	static const char k_gpxtpx_open[] =
30	  "      <gpxtpx:TrackPointExtension xmlns:gpxtpx=\""
31	  GPX_SENSOR_NS_GPXTPX "\">\n";
32	
33	/**
34	 * @brief 将传感器扩展格式化为 GPX 1.1 <extensions> 内部 XML 片段。
35	 *
36	 * @param data  gpx_sensor_ext_t 指针
37	 * @param buf   输出缓冲区
38	 * @param size  缓冲区容量（字节）
39	 * @return 写入字节数（>0），无内容时 0，失败返回负 errno
40	 */
41	static int gpx_sensor_format(const void *data, char *buf, size_t size)
42	{
43	  const gpx_sensor_ext_t *sensor = data;
44	  int off = 0;
45	  int n;
46	
47	  if (sensor == NULL || buf == NULL || size == 0)
48	    {
49	      return -EINVAL;
50	    }
51	
52	  if (sensor->has_hr || sensor->has_cad || sensor->has_speed)
53	    {
54	      n = snprintf(buf + off, size - (size_t)off, "%s", k_gpxtpx_open);
55	      if (n < 0 || (size_t)off + (size_t)n >= size)
56	        {
57	          return -ENOMEM;
58	        }
59	
60	      off += n;
61	
62	      if (sensor->has_hr)
63	        {
64	          n = snprintf(buf + off, size - (size_t)off,
65	                       "        <gpxtpx:hr>%u</gpxtpx:hr>\n",
66	                       (unsigned)sensor->hr);
67	          if (n < 0 || (size_t)off + (size_t)n >= size)
68	            {
69	              return -ENOMEM;
70	            }
71	
72	          off += n;
73	        }
74	
75	      if (sensor->has_cad)
76	        {
77	          n = snprintf(buf + off, size - (size_t)off,
78	                       "        <gpxtpx:cad>%u</gpxtpx:cad>\n",
79	                       (unsigned)sensor->cad);
80	          if (n < 0 || (size_t)off + (size_t)n >= size)
81	            {
82	              return -ENOMEM;
83	            }
84	
85	          off += n;
86	        }
87	
88	      if (sensor->has_speed)
89	        {
90	          /* gpxtpx:speed 的单位是 m/s（Garmin TrackPointExtension v1）。 */
91	          n = snprintf(buf + off, size - (size_t)off,
92	                       "        <gpxtpx:speed>%.2f</gpxtpx:speed>\n",
93	                       (double)sensor->speed_mps);
94	          if (n < 0 || (size_t)off + (size_t)n >= size)
95	            {
96	              return -ENOMEM;
97	            }
98	
99	          off += n;
100	        }
101	
102	      n = snprintf(buf + off, size - (size_t)off,
103	                   "      </gpxtpx:TrackPointExtension>\n");
104	      if (n < 0 || (size_t)off + (size_t)n >= size)
105	        {
106	          return -ENOMEM;
107	        }
108	
109	      off += n;
110	    }
111	
112	  if (sensor->has_power)
113	    {
114	      /* Garmin PowerExtension v1 只定义 PowerInWatts 一个元素（xsd:unsignedShort，
115	       * 单位 W），直接挂在 <extensions> 下、没有外层包裹。 */
116	      n = snprintf(buf + off, size - (size_t)off,
117	                   "      <gpxpx:PowerInWatts xmlns:gpxpx=\"%s\">%u</gpxpx:PowerInWatts>\n",
118	                   GPX_SENSOR_NS_POWER, (unsigned)sensor->power_w);
119	      if (n < 0 || (size_t)off + (size_t)n >= size)
120	        {
121	          return -ENOMEM;
122	        }
123	
124	      off += n;
125	    }
126	
127	  return off;
128	}
