130	/**
131	 * @brief 从扩展 XML 中解析 <gpxtpx:hr> 字段。
132	 *
133	 * @param xml     扩展 XML 片段
134	 * @param sensor  输出结构（写入 hr 与 has_hr）
135	 * @return 0 解析成功，1 未找到，负 errno 解析错误
136	 */
137	static int gpx_sensor_parse_hr(const char *xml, gpx_sensor_ext_t *sensor)
138	{
139	  const char *tag = "<gpxtpx:hr>";
140	  const char *start;
141	  char *end;
142	  unsigned long val;
143	
144	  start = strstr(xml, tag);
145	  if (start == NULL)
146	    {
147	      return 1;
148	    }
149	
150	  start += strlen(tag);
151	  val = strtoul(start, &end, 10);
152	  if (end == start)
153	    {
154	      return -EINVAL;
155	    }
156	
157	  sensor->hr = (uint16_t)val;
158	  sensor->has_hr = true;
159	  return 0;
160	}
