162	/**
163	 * @brief 从扩展 XML 中解析 <gpxtpx:cad> 字段。
164	 *
165	 * @param xml     扩展 XML 片段
166	 * @param sensor  输出结构（写入 cad 与 has_cad）
167	 * @return 0 解析成功，1 未找到，负 errno 解析错误
168	 */
169	static int gpx_sensor_parse_cad(const char *xml, gpx_sensor_ext_t *sensor)
170	{
171	  const char *tag = "<gpxtpx:cad>";
172	  const char *start;
173	  char *end;
174	  unsigned long val;
