194	/**
195	 * @brief 从扩展 XML 中解析 <gpxtpx:speed> 字段（m/s）。
196	 *
197	 * @param xml     扩展 XML 片段
198	 * @param sensor  输出结构（写入 speed_mps 与 has_speed）
199	 * @return 0 解析成功，1 未找到，负 errno 解析错误
200	 */
201	static int gpx_sensor_parse_speed(const char *xml, gpx_sensor_ext_t *sensor)
202	{
203	  const char *tag = "<gpxtpx:speed>";
204	  const char *start;
205	  char *end;
206	  double val;
207	
208	  start = strstr(xml, tag);
209	  if (start == NULL)
210	    {
211	      return 1;
212	    }
213	
214	  start += strlen(tag);
215	  val = strtod(start, &end);
216	  if (end == start)
217	    {
218	      return -EINVAL;
219	    }
220	
221	  sensor->speed_mps = (float)val;
222	  sensor->has_speed = true;
223	  return 0;
224	}
