226	/**
227	 * @brief 从扩展 XML 中解析 <gpxpx:PowerInWatts> 字段（W）。
228	 *
229	 * @param xml     扩展 XML 片段
230	 * @param sensor  输出结构（写入 power_w 与 has_power）
231	 * @return 0 解析成功，1 未找到，负 errno 解析错误
232	 */
233	static int gpx_sensor_parse_power(const char *xml, gpx_sensor_ext_t *sensor)
234	{
235	  /* 开标签带命名空间声明（xmlns:gpxpx=…），所以不能直接 strstr 找 "<…>"：
236	   * 先定位标签名，再跳到它的 '>' 之后取数值。 */
237	  const char *tag = "<gpxpx:PowerInWatts";
238	  const char *start;
239	  char *end;
240	  unsigned long val;
241	
242	  start = strstr(xml, tag);
243	  if (start == NULL)
244	    {
245	      return 1;
246	    }
247	
248	  start = strchr(start, '>');
249	  if (start == NULL)
250	    {
251	      return -EINVAL;
252	    }
253	
254	  start++;
255	  val = strtoul(start, &end, 10);
256	  if (end == start)
257	    {
258	      return -EINVAL;
259	    }
260	
261	  sensor->power_w = (uint16_t)val;
262	  sensor->has_power = true;
263	  return 0;
264	}
265	
266	/**
267	 * @brief 解析 <extensions> 内部 XML 到 gpx_sensor_ext_t。
268	 *
269	 * @param xml   扩展 XML（不必 NUL 结尾，使用 len）
270	 * @param len   xml 长度（字节）
271	 * @param data  输出 gpx_sensor_ext_t 指针
272	 * @return 0 匹配并解析成功，1 不匹配（跳过），负 errno 错误
273	 */
274	static int gpx_sensor_parse(const char *xml, size_t len, void *data)
275	{
276	  gpx_sensor_ext_t scratch;
277	  gpx_sensor_ext_t *sensor = data;
278	  char *copy = NULL;
279	  const char *src;
280	  int ret_hr;
281	  int ret_cad;
282	  int ret_speed;
283	  int ret_power;
284	  bool matched = false;
285	
286	  if (xml == NULL || !gpx_ext_data_bound(sensor))
287	    {
288	      return -EINVAL;
289	    }
290	
291	  if (len == 0)
292	    {
293	      return 1;
294	    }
295	
296	  /* 调用方已 NUL 结尾（流式 scratch）则免拷。 */
297	  if (xml[len] == '\0')
298	    {
299	      src = xml;
300	    }
301	  else
302	    {
303	      copy = gpx_port_malloc(len + 1);
304	      if (copy == NULL)
305	        {
306	          return -ENOMEM;
307	        }
308	
309	      memcpy(copy, xml, len);
310	      copy[len] = '\0';
311	      src = copy;
312	    }
313	
314	  memset(&scratch, 0, sizeof(scratch));
315	  ret_hr = gpx_sensor_parse_hr(src, &scratch);
316	  if (ret_hr < 0)
317	    {
318	      gpx_port_free(copy);
319	      return ret_hr;
320	    }
321	
322	  ret_cad = gpx_sensor_parse_cad(src, &scratch);
323	  if (ret_cad < 0)
324	    {
325	      gpx_port_free(copy);
326	      return ret_cad;
327	    }
328	
329	  ret_speed = gpx_sensor_parse_speed(src, &scratch);
330	  if (ret_speed < 0)
331	    {
332	      gpx_port_free(copy);
333	      return ret_speed;
334	    }
335	
336	  ret_power = gpx_sensor_parse_power(src, &scratch);
337	  if (ret_power < 0)
338	    {
339	      gpx_port_free(copy);
340	      return ret_power;
341	    }
342	
343	  gpx_port_free(copy);
344	
345	  if (ret_hr == 0 || ret_cad == 0 || ret_speed == 0 || ret_power == 0)
346	    {
347	      matched = true;
348	    }
349	
350	  if (!matched)
351	    {
352	      return 1;
353	    }
354	
355	  *sensor = scratch;
356	  return 0;
357	}
