359	/**
360	 * @brief 将传感器扩展格式化为可读文本（decode / NSH 打印用）。
361	 *
362	 * @param data  gpx_sensor_ext_t 指针
363	 * @param buf   输出缓冲区
364	 * @param size  缓冲区容量（字节）
365	 * @return 写入字节数（>0），无内容时 0，失败返回负 errno
366	 */
367	static int gpx_sensor_print(const void *data, char *buf, size_t size)
368	{
369	  const gpx_sensor_ext_t *sensor = data;
370	  int off = 0;
371	  int n;
372	
373	  if (sensor == NULL || buf == NULL || size == 0)
374	    {
375	      return -EINVAL;
376	    }
377	
378	  if (sensor->has_hr)
379	    {
380	      n = snprintf(buf + off, size - (size_t)off, " hr=%u",
381	                   (unsigned)sensor->hr);
382	      if (n < 0 || (size_t)off + (size_t)n >= size)
383	        {
384	          return -ENOMEM;
385	        }
386	
387	      off += n;
388	    }
389	
390	  if (sensor->has_cad)
391	    {
392	      n = snprintf(buf + off, size - (size_t)off, " cad=%u",
393	                   (unsigned)sensor->cad);
394	      if (n < 0 || (size_t)off + (size_t)n >= size)
395	        {
396	          return -ENOMEM;
397	        }
398	
399	      off += n;
400	    }
401	
402	  if (sensor->has_speed)
403	    {
404	      /* 与文件里一致用 m/s；decode 出来 ÷3.6 才是 km/h。 */
405	      n = snprintf(buf + off, size - (size_t)off, " speed=%.2f",
406	                   (double)sensor->speed_mps);
407	      if (n < 0 || (size_t)off + (size_t)n >= size)
408	        {
409	          return -ENOMEM;
410	        }
411	
412	      off += n;
413	    }
414	
415	  if (sensor->has_power)
416	    {
417	      n = snprintf(buf + off, size - (size_t)off, " power=%u",
418	                   (unsigned)sensor->power_w);
419	      if (n < 0 || (size_t)off + (size_t)n >= size)
420	        {
421	          return -ENOMEM;
422	        }
423	
424	      off += n;
425	    }
426	
427	  return off;
428	}
