430	/**
431	 * @brief 注册传感器扩展（format + parse + print）。
432	 *
433	 * @return slot 编号 0 … GPX_EXT_SLOT_MAX-1，失败返回负 errno
434	 */
435	int gpx_ext_sensor_register(void)
436	{
437	  gpx_ext_desc_t desc;
438	
439	  memset(&desc, 0, sizeof(desc));
440	  desc.name = "sensor";
441	  desc.data_size = sizeof(gpx_sensor_ext_t);
442	  desc.fmt_max = GPX_EXT_SENSOR_FMT_MAX;
443	  /* 四个读数 + 风向的文字都比显式数字长（" speed=12.34 power=9999"），
444	   * decode/NSH 打印缓冲按这个值分配，给小了会 -ENOMEM 少打字段。 */
445	  desc.print_max = 64;
446	  desc.format = gpx_sensor_format;
447	  desc.parse = gpx_sensor_parse;
448	  desc.print = gpx_sensor_print;
449	
450	  return gpx_ext_register(&desc);
451	}
