456	 * @param slot  gpx_ext_sensor_register() 返回的 slot
457	 * @return 0 成功，负 errno 失败
458	 */
459	int gpx_ext_sensor_unregister(int slot)
460	{
461	  return gpx_ext_unregister(slot);
462	}

