6	/// GPX 1.1 最小读写：抽 trkpt/rtept，写 rte 或 trk。
7	abstract class GpxUtil {
8	  static final _ptRe = RegExp(
9	    r'<(?:trkpt|rtept)\s+[^>]*lat="([+-]?\d+(?:\.\d+)?)"[^>]*lon="([+-]?\d+(?:\.\d+)?)"',
10	    caseSensitive: false,
11	  );
12	
13	  static final _ptReSwap = RegExp(
14	    r'<(?:trkpt|rtept)\s+[^>]*lon="([+-]?\d+(?:\.\d+)?)"[^>]*lat="([+-]?\d+(?:\.\d+)?)"',
15	    caseSensitive: false,
16	  );
17	
18	  static final _nameRe = RegExp(
19	    r'<name>\s*([^<]+)\s*</name>',
20	    caseSensitive: false,
21	  );
22	
23	  static final _timeRe = RegExp(
24	    r'<time>\s*([^<]+)\s*</time>',
25	    caseSensitive: false,
26	  );
27	
28	  static final _trkptRe = RegExp(
29	    r'<trkpt\b([^>]*)>([\s\S]*?)</trkpt>',
30	    caseSensitive: false,
31	  );
32	
33	  static final _trkptSelfRe = RegExp(
34	    r'<trkpt\b([^>]*)\s*/>',
35	    caseSensitive: false,
36	  );
37	
38	  static final _metaOpenRe = RegExp(r'<metadata\b[^>]*>', caseSensitive: false);
39	
40	  static final _gpxOpenRe = RegExp(r'<gpx\b[^>]*>', caseSensitive: false);
41	
42	  /// 判断一段字节流像不像 GPX。
43	  ///
44	  /// 用途：Android 的文件选择器**没法按扩展名过滤** —— `file_selector_android`
45	  /// 用系统 `MimeTypeMap` 把 `extensions` 翻成 MIME，而 `gpx` 没有注册项会被
46	  /// 丢掉（插件日志 `Extension not supported: gpx`），只剩 `xml` → `text/xml`，
47	  /// 于是选择器被锁死在 `text/xml`，GPX 文件全部变灰选不中。所以选择时不过滤，
48	  /// 选完之后用这个函数自己认。
49	  ///
50	  /// 只看**前 64 KiB**：GPX 根元素一定在最前面，没必要把几十 MB 全解成字符串。
51	  static bool looksLikeGpx(List<int> bytes) {
52	    if (bytes.isEmpty) return false;
53	
54	    final n = bytes.length > 65536 ? 65536 : bytes.length;
55	    // latin1 逐字节映射，不会因为多字节 UTF-8 截断而抛异常。
56	    final head = String.fromCharCodes(bytes.take(n));
57	    return _gpxOpenRe.hasMatch(head);
58	  }
59	
60	  static final _openPtRe = RegExp(
61	    r'<(?:trkpt|rtept)\b([^>]*)>([\s\S]*?)</(?:trkpt|rtept)>',
62	    caseSensitive: false,
63	  );
64	
65	  static final _latAttrRe = RegExp(
66	    r'\blat="([+-]?\d+(?:\.\d+)?)"',
67	    caseSensitive: false,
68	  );
69	
70	  static final _lonAttrRe = RegExp(
71	    r'\blon="([+-]?\d+(?:\.\d+)?)"',
72	    caseSensitive: false,
73	  );
74	
75	  static final _eleRe = RegExp(
76	    r'<ele>\s*([+-]?\d+(?:\.\d+)?)\s*</ele>',
77	    caseSensitive: false,
78	  );
79	
80	  static final _hrRe = RegExp(
81	    r'<(?:[\w.]+:)?hr>\s*(\d{1,3})\s*</(?:[\w.]+:)?hr>',
82	    caseSensitive: false,
83	  );
84	
85	  /// 踏频：`<gpxtpx:cad>85</gpxtpx:cad>`。
86	  static final _cadRe = RegExp(
87	    r'<(?:[\w.]+:)?cad>\s*([+-]?\d+)\s*</(?:[\w.]+:)?cad>',
88	    caseSensitive: false,
89	  );
90	
91	  /// 功率扩展：开标签带 `xmlns`，所以属性部分要放过。
92	  /// `<gpxpx:PowerInWatts xmlns:...>210</gpxpx:PowerInWatts>`
93	  static final _powerExtRe = RegExp(
94	    r'<(?:[\w.]+:)?PowerInWatts\b[^>]*>\s*([+-]?\d+(?:\.\d+)?)\s*'
95	    r'</(?:[\w.]+:)?PowerInWatts>',
96	    caseSensitive: false,
97	  );
98	
99	  /// 第三方 GPX 常见的裸 `<power>210</power>`。
100	  static final _powerRe = RegExp(
101	    r'<(?:[\w.]+:)?power>\s*([+-]?\d+(?:\.\d+)?)\s*</(?:[\w.]+:)?power>',
102	    caseSensitive: false,
103	  );
104	
105	  /// 设备速度：`<gpxtpx:speed>6.50</gpxtpx:speed>`，单位 m/s。
106	  static final _speedRe = RegExp(
107	    r'<(?:[\w.]+:)?speed>\s*([+-]?\d+(?:\.\d+)?)\s*</(?:[\w.]+:)?speed>',
108	    caseSensitive: false,
109	  );
110	
111	  static final _extClimbRe = RegExp(
112	    r'<cumulativeClimb>\s*([+-]?\d+(?:\.\d+)?)\s*</cumulativeClimb>',
113	    caseSensitive: false,
114	  );
115	
116	  static const _hrMinBpm = 30;
117	  static const _hrMaxBpm = 220;
118	  static const _cadMaxRpm = 250; // 0 合法＝滑行，只挡离谱值。
119	  static const _powerMaxW = 2500;
120	  static const _speedMaxMps = 42.0; // 150 km/h
121	
122	  /// 解析名称、点列、以及文件内可信的起止时间。
123	  static GpxSummary parse(String xml) {
124	    var name = '';
125	    final m = _nameRe.firstMatch(xml);
126	    if (m != null) {
127	      name = m.group(1)!.trim();
128	    }
129	
130	    final raw = _extractPts(xml);
131	    final points = [for (final p in raw) p.ll];
132	    final km = distanceKm(points);
133	    final times = plausibleTimes(xml);
134	    final start = times.isEmpty ? null : times.first;
135	    final end = times.isEmpty ? null : times.last;
136	    Duration? duration;
137	    if (start != null && end != null) {
138	      final d = end.difference(start);
139	      if (d.inSeconds >= 15) duration = d;
140	    }
141	    final speeds = _speedSeries(raw);
142	    final hr = _hrSeries(raw);
143	    final cad = _cadSeries(raw);
144	    final pw = _powerSeries(raw);
145	    final elev = _elev(raw);
146	    var gain = elev.gain;
147	    final extClimb = _extClimbRe.firstMatch(xml);
148	    if (gain == null && extClimb != null) {
149	      final v = double.tryParse(extClimb.group(1)!);
150	      if (v != null && v > 0.5) gain = v;
151	    }
152	    double? avg;
153	    if (duration != null && km > 0.05) {
154	      final hours = duration.inMilliseconds / 3600000.0;
155	      if (hours > 0) avg = km / hours;
156	    }
157	    if (avg == null && speeds.points.isNotEmpty) {
158	      var s = 0.0;
159	      for (final p in speeds.points) {
160	        s += p.value;
161	      }
162	      avg = s / speeds.points.length;
163	    }
164	    var atPoint = speeds.atPoint;
165	    if (avg != null && avg > 0 && atPoint.length > 1) {
166	      var any = false;
167	      for (final v in atPoint) {
168	        if (v > 0.2) {
169	          any = true;
170	          break;
171	        }
172	      }
173	      if (!any) {
174	        atPoint = List<double>.filled(atPoint.length, avg);
175	        atPoint[0] = 0;
176	      }
177	    }
178	    return GpxSummary(
179	      name: name,
180	      points: points,
181	      distanceKm: km,
182	      startTime: start,
183	      endTime: end,
184	      duration: duration,
185	      avgSpeedKmh: avg,
186	      maxSpeedKmh: speeds.max,
187	      elevGainM: gain,
188	      elevLossM: elev.loss,
189	      minEleM: elev.min,
190	      maxEleM: elev.max,
191	      avgHrBpm: hr.avg,
192	      maxHrBpm: hr.max,
193	      hrPoints: hr.points,
194	      avgCadenceRpm: cad.avg,
195	      maxCadenceRpm: cad.max,
196	      cadPoints: cad.points,
197	      avgPowerW: pw.avg,
198	      maxPowerW: pw.max,
199	      powerPoints: pw.points,
200	      pointCadenceRpm: [for (final p in raw) p.cad],
201	      pointPowerW: [for (final p in raw) p.pw],
202	      pointHrBpm: [for (final p in raw) p.hr],
203	      speedPoints: speeds.points,
204	      pointSpeedsKmh: speeds.atPoint,
205	    );
206	  }
