208	  static List<_GpxPt> _extractPts(String xml) {
209	    final out = <_GpxPt>[];
210	    for (final match in _openPtRe.allMatches(xml)) {
211	      final ll = _llFromAttrs(match.group(1)!);
212	      if (ll == null) continue;
213	      final inner = match.group(2)!;
214	      final eleM = _eleRe.firstMatch(inner);
215	      final timeM = _timeRe.firstMatch(inner);
216	      DateTime? t;
217	      if (timeM != null) {
218	        t = tryParseUtc(timeM.group(1)!);
219	        if (t != null && !isPlausibleTime(t)) t = null;
220	      }
221	      out.add((
222	        ll: ll,
223	        ele: eleM == null ? null : double.tryParse(eleM.group(1)!),
224	        time: t,
225	        hr: _hrFromInner(inner),
226	        cad: _cadFromInner(inner),
227	        pw: _powerFromInner(inner),
228	        spdMps: _speedFromInner(inner),
229	      ));
230	    }
231	    if (out.isNotEmpty) return out;
232	    for (final match in _ptRe.allMatches(xml)) {
233	      final lat = double.tryParse(match.group(1)!);
234	      final lon = double.tryParse(match.group(2)!);
235	      if (lat != null && lon != null) {
236	        out.add((
237	          ll: LatLng(lat, lon),
238	          ele: null,
239	          time: null,
240	          hr: null,
241	          cad: null,
242	          pw: null,
243	          spdMps: null,
244	        ));
245	      }
246	    }
247	    if (out.isNotEmpty) return out;
248	    for (final match in _ptReSwap.allMatches(xml)) {
249	      final lon = double.tryParse(match.group(1)!);
250	      final lat = double.tryParse(match.group(2)!);
251	      if (lat != null && lon != null) {
252	        out.add((
253	          ll: LatLng(lat, lon),
254	          ele: null,
255	          time: null,
256	          hr: null,
257	          cad: null,
258	          pw: null,
259	          spdMps: null,
260	        ));
261	      }
262	    }
263	    return out;
264	  }
