305	  /// 逐点速度。优先用码表记录的设备速度（m/s → km/h），没有才用相邻点
306	  /// 距离 / 时间差推算；都缺时沿用上一个值（第 0 点为 0）。
307	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
308	      _speedSeries(List<_GpxPt> pts) {
309	    var maxV = 0.0;
310	    final series = <RideSeriesPoint>[];
311	    final atPoint = List<double>.filled(pts.length, 0);
312	    var last = 0.0;
313	    for (var i = 0; i < pts.length; i++) {
314	      var v = last;
315	      final dev = pts[i].spdMps;
316	      if (dev != null) {
317	        // 设备速度不受 0.8~60 s 时间窗限制（GNSS 丢点时照样可信）。
318	        v = dev * 3.6;
319	        series.add(RideSeriesPoint(time: pts[i].time, value: v));
320	        if (v > maxV) maxV = v;
321	      } else if (i > 0) {
322	        final a = pts[i - 1].time;
323	        final b = pts[i].time;
324	        if (a != null && b != null) {
325	          final sec = b.difference(a).inMilliseconds / 1000.0;
326	          if (sec >= 0.8 && sec <= 60) {
327	            final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
328	            final raw = km / (sec / 3600.0);
329	            if (raw > 0 && raw < 80) {
330	              v = raw;
331	              series.add(RideSeriesPoint(time: b, value: v));
332	              if (v > maxV) maxV = v;
333	            }
334	          }
335	        }
336	      }
337	      atPoint[i] = v;
338	      last = v;
339	    }
340	    return (
341	      max: maxV > 0.5 ? maxV : null,
342	      points: series,
343	      atPoint: atPoint,
344	    );
345	  }
346	
347	  /// 沿轨迹每整公里一个点。
348	  ///
349	  /// [at] 是它落在轨迹上的位置，用「点下标」表示（`4.5` = 第 4、5 点之间）。回放时
350	  /// 用它判断线画到没有 —— 缺了它就只能猜，牌子要么全出来要么全不出来。
351	  static List<({LatLng ll, int km, double at})> kmMarkers(
352	    List<LatLng> points, {
353	    double intervalKm = 1,
354	    int maxMarks = 120,
355	  }) {
356	    final out = <({LatLng ll, int km, double at})>[];
357	    if (points.length < 2 || intervalKm <= 0) return out;
358	    var acc = 0.0;
359	    var next = intervalKm;
360	    var n = 1;
361	    for (var i = 1; i < points.length; i++) {
362	      final d = _haversineKm(points[i - 1], points[i]);
363	      if (d <= 0) continue;
364	      while (acc + d >= next && n <= maxMarks) {
365	        final t = ((next - acc) / d).clamp(0.0, 1.0);
366	        final a = points[i - 1];
367	        final b = points[i];
368	        out.add((
369	          ll: LatLng(
370	            a.latitude + (b.latitude - a.latitude) * t,
371	            a.longitude + (b.longitude - a.longitude) * t,
372	          ),
373	          km: n,
374	          at: (i - 1) + t,
375	        ));
376	        n++;
377	        next += intervalKm;
378	      }
379	      acc += d;
380	    }
381	    return out;
382	  }
383	
384	  /// 每个点的累计骑行时间（秒，从 0 起）。
385	  ///
386	  /// 用相邻两点的距离除以该点速度累加，还原「这段路实际花了多久」，回放时才能
387	  /// 按运动本身的速度推进（快的地方画得快）。比按点数平均更贴近真实节奏。
388	  /// 速度缺失或异常（<=0.2 km/h）时用 [fallbackKmh] 兜底。
389	  static List<double> cumulativeRideSeconds(
390	    List<LatLng> points,
391	    List<double> speedsAtPoint, {
392	    double fallbackKmh = 18,
393	  }) {
394	    final n = points.length;
395	    final out = List<double>.filled(n, 0);
396	    if (n < 2) return out;
397	    var acc = 0.0;
398	    for (var i = 1; i < n; i++) {
399	      final d = _haversineKm(points[i - 1], points[i]);
400	      var v = i < speedsAtPoint.length ? speedsAtPoint[i] : fallbackKmh;
401	      if (!(v > 0.2)) v = fallbackKmh;
402	      acc += d / v * 3600.0;
403	      out[i] = acc;
404	    }
405	    return out;
406	  }
