408	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _hrSeries(
409	    List<_GpxPt> pts,
410	  ) {
411	    final series = <RideSeriesPoint>[];
412	    var sum = 0;
413	    var maxV = 0;
414	    for (final p in pts) {
415	      final hr = p.hr;
416	      if (hr == null) continue;
417	      series.add(RideSeriesPoint(time: p.time, value: hr.toDouble()));
418	      sum += hr;
419	      if (hr > maxV) maxV = hr;
420	    }
421	    if (series.isEmpty) {
422	      return (avg: null, max: null, points: const []);
423	    }
424	    return (
425	      avg: (sum / series.length).round(),
426	      max: maxV,
427	      points: series,
428	    );
429	  }
