431	  /// 踏频序列与统计。`0` 是「在滑行」，算有效样本但不进平均。
432	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _cadSeries(
433	    List<_GpxPt> pts,
434	  ) {
435	    final series = <RideSeriesPoint>[];
436	    var sum = 0;
437	    var n = 0;
438	    var maxV = 0;
439	    for (final p in pts) {
440	      final cad = p.cad;
441	      if (cad == null) continue;
442	      series.add(RideSeriesPoint(time: p.time, value: cad.toDouble()));
443	      if (cad > 0) {
444	        sum += cad;
445	        n++;
446	      }
447	      if (cad > maxV) maxV = cad;
448	    }
449	    if (series.isEmpty) {
450	      return (avg: null, max: null, points: const []);
451	    }
452	    return (
453	      avg: n > 0 ? (sum / n).round() : null,
454	      max: maxV,
455	      points: series,
456	    );
457	  }
