459	  /// 功率序列与统计。口径与踏频刻意不同：`0 W` 是真实样本，计入平均。
460	  static ({double? avg, double? max, List<RideSeriesPoint> points})
461	      _powerSeries(List<_GpxPt> pts) {
462	    final series = <RideSeriesPoint>[];
463	    var sum = 0.0;
464	    var maxV = 0.0;
465	    for (final p in pts) {
466	      final pw = p.pw;
467	      if (pw == null) continue;
468	      series.add(RideSeriesPoint(time: p.time, value: pw.toDouble()));
469	      sum += pw;
470	      if (pw > maxV) maxV = pw.toDouble();
471	    }
472	    if (series.isEmpty) {
473	      return (avg: null, max: null, points: const []);
474	    }
475	    return (avg: sum / series.length, max: maxV, points: series);
476	  }
