478	  static ({double? gain, double? loss, double? min, double? max}) _elev(
479	    List<_GpxPt> pts,
480	  ) {
481	    double? minV;
482	    double? maxV;
483	    var gain = 0.0;
484	    var loss = 0.0;
485	    double? prev;
486	    var n = 0;
487	    for (final p in pts) {
488	      final e = p.ele;
489	      if (e == null) continue;
490	      n++;
491	      minV = minV == null ? e : math.min(minV, e);
492	      maxV = maxV == null ? e : math.max(maxV, e);
493	      if (prev != null) {
494	        final d = e - prev;
495	        if (d > 0.8) gain += d;
496	        if (d < -0.8) loss += -d;
497	      }
498	      prev = e;
499	    }
500	    if (n < 2) {
501	      return (gain: null, loss: null, min: minV, max: maxV);
502	    }
503	    return (
504	      gain: gain > 0.5 ? gain : null,
505	      loss: loss > 0.5 ? loss : null,
506	      min: minV,
507	      max: maxV,
508	    );
509	  }
