536	  /// 心率区间累计（热身 / 燃脂 / 有氧 / 无氧 / 极限）。
537	  static List<Duration> hrZoneDurations(
538	    List<RideSeriesPoint> pts, {
539	    Duration? total,
540	  }) {
541	    final zones = List<Duration>.filled(5, Duration.zero);
542	    if (pts.isEmpty) return zones;
543	    final fallbackMs =
544	        (total?.inMilliseconds ?? pts.length * 1000) ~/ pts.length;
545	    for (var i = 0; i < pts.length; i++) {
546	      var ms = fallbackMs;
547	      if (i + 1 < pts.length) {
548	        final a = pts[i].time;
549	        final b = pts[i + 1].time;
550	        if (a != null && b != null) {
551	          final d = b.difference(a).inMilliseconds;
552	          if (d > 0 && d <= 120000) ms = d;
553	        }
554	      }
555	      if (ms <= 0) continue;
556	      final z = hrZoneIndex(pts[i].value.round());
557	      zones[z] += Duration(milliseconds: ms);
558	    }
559	    return zones;
560	  }
