571	  /// 无热量字段时的估算：有心率用 Keytel 简化，否则按里程。
572	  static int estimateKcal({
573	    int? avgHrBpm,
574	    Duration? duration,
575	    double distanceKm = 0,
576	  }) {
577	    final minutes = (duration?.inSeconds ?? 0) / 60.0;
578	    if (avgHrBpm != null && avgHrBpm > 0 && minutes > 0) {
579	      return math.max(1, (avgHrBpm * minutes * 0.03).round());
580	    }
581	    if (distanceKm > 0.001) {
582	      return math.max(1, (distanceKm * 30).round());
583	    }
584	    return 0;
585	  }
