627	  /// 相邻点球面距离之和，千米。
628	  static double distanceKm(List<LatLng> points) {
629	    var sum = 0.0;
630	    for (var i = 1; i < points.length; i++) {
631	      sum += _haversineKm(points[i - 1], points[i]);
632	    }
633	    return sum;
634	  }
635	
636	  static double _haversineKm(LatLng a, LatLng b) {
637	    const r = 6371.0;
638	    final dLat = _rad(b.latitude - a.latitude);
639	    final dLon = _rad(b.longitude - a.longitude);
640	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
641	        math.cos(_rad(a.latitude)) *
642	            math.cos(_rad(b.latitude)) *
643	            math.sin(dLon / 2) *
644	            math.sin(dLon / 2);
645	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
646	  }
647	
648	  static double _rad(double deg) => deg * math.pi / 180;
649	
650	  /// 列表缩略图用：保留起终点，中间均匀抽点。
651	  static List<LatLng> previewTrack(List<LatLng> points, {int max = 48}) {
652	    if (points.length <= 2) return List<LatLng>.from(points);
653	    if (points.length <= max) return List<LatLng>.from(points);
654	    final last = points.length - 1;
655	    final out = <LatLng>[];
656	    for (var i = 0; i < max; i++) {
657	      final idx = ((last * i) / (max - 1)).round();
658	      if (out.isEmpty || out.last != points[idx]) {
659	        out.add(points[idx]);
660	      }
661	    }
662	    if (out.last != points.last) out.add(points.last);
663	    return out;
664	  }
