666	  /// 稀疏途经点：route。写入 metadata 时间（手机时钟）。
667	  static String writeRoute({
668	    required String name,
669	    required List<LatLng> points,
670	    List<String>? labels,
671	    DateTime? timeUtc,
672	  }) {
673	    final metaTime = formatUtc(timeUtc ?? DateTime.now().toUtc());
674	    final buf = StringBuffer()
675	      ..writeln('<?xml version="1.0" encoding="UTF-8"?>')
676	      ..writeln(
677	        '<gpx version="1.1" creator="Helm One App" '
678	        'xmlns="http://www.topografix.com/GPX/1/1">',
679	      )
680	      ..writeln(
681	        '  <metadata><name>${_esc(name)}</name>'
682	        '<time>$metaTime</time></metadata>',
683	      )
684	      ..writeln('  <rte>')
685	      ..writeln('    <name>${_esc(name)}</name>');
686	    for (var i = 0; i < points.length; i++) {
687	      final p = points[i];
688	      final label = (labels != null && i < labels.length && labels[i].isNotEmpty)
689	          ? labels[i]
690	          : '${i + 1}';
691	      buf.writeln(
692	        '    <rtept lat="${p.latitude.toStringAsFixed(7)}" '
693	        'lon="${p.longitude.toStringAsFixed(7)}">'
694	        '<name>${_esc(label)}</name></rtept>',
695	      );
696	    }
