756	  static String _stampTrkpts(String xml, DateTime endUtc) {
757	    final blocks = _trkptRe.allMatches(xml).toList();
758	    if (blocks.isEmpty) {
759	      return _stampSelfClosing(xml, endUtc);
760	    }
761	    final n = blocks.length;
762	    final start = n <= 1
763	        ? endUtc
764	        : endUtc.subtract(Duration(seconds: n - 1));
765	    var out = xml;
766	    for (var i = n - 1; i >= 0; i--) {
767	      final m = blocks[i];
768	      final t = formatUtc(start.add(Duration(seconds: i)));
769	      out = out.replaceRange(m.start, m.end, _stampOneTrkpt(m.group(0)!, t));
770	    }
771	    return out;
772	  }
