774	  static String _stampSelfClosing(String xml, DateTime endUtc) {
775	    final blocks = _trkptSelfRe.allMatches(xml).toList();
776	    if (blocks.isEmpty) return xml;
777	    final n = blocks.length;
778	    final start = n <= 1
779	        ? endUtc
780	        : endUtc.subtract(Duration(seconds: n - 1));
781	    var out = xml;
782	    for (var i = n - 1; i >= 0; i--) {
783	      final m = blocks[i];
784	      final attrs = m.group(1) ?? '';
785	      final t = formatUtc(start.add(Duration(seconds: i)));
786	      out = out.replaceRange(
787	        m.start,
788	        m.end,
789	        '<trkpt$attrs><time>$t</time></trkpt>',
790	      );
791	    }
792	    return out;
793	  }
