795	  static String _stampOneTrkpt(String block, String iso) {
796	    if (_timeRe.hasMatch(block)) {
797	      return block.replaceFirst(_timeRe, '<time>$iso</time>');
798	    }
799	    return block.replaceFirst(
800	      RegExp(r'</trkpt>', caseSensitive: false),
801	      '<time>$iso</time></trkpt>',
