805	  static String _ensureMetadataTime(String xml, DateTime t) {
806	    final iso = formatUtc(t);
807	    final meta = _metaOpenRe.firstMatch(xml);
808	    if (meta != null) {
809	      final closeIdx = xml.toLowerCase().indexOf('</metadata>', meta.end);
810	      if (closeIdx > meta.end) {
811	        final inner = xml.substring(meta.end, closeIdx);
812	        if (_timeRe.hasMatch(inner)) {
813	          final stamped = inner.replaceFirst(_timeRe, '<time>$iso</time>');
814	          return xml.substring(0, meta.end) + stamped + xml.substring(closeIdx);
815	        }
816	        return '${xml.substring(0, meta.end)}<time>$iso</time>${xml.substring(meta.end)}';
817	      }
818	    }
819	    final gpx = _gpxOpenRe.firstMatch(xml);
820	    if (gpx == null) return xml;
821	    return '${xml.substring(0, gpx.end)}\n'
822	        '  <metadata><time>$iso</time></metadata>'
823	        '${xml.substring(gpx.end)}';
824	  }
