844	  /// 码表列表文件名上限约 31 字符（含 .gpx）。
845	  static String safeFileName(String raw, {int maxChars = 31}) {
846	    var stem = raw.trim();
847	    if (stem.toLowerCase().endsWith('.gpx')) {
848	      stem = stem.substring(0, stem.length - 4);
849	    }
850	    final buf = StringBuffer();
851	    for (final r in stem.runes) {
852	      final c = String.fromCharCode(r);
853	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
854	        buf.write(c);
855	      } else if (c == ' ') {
856	        buf.write('_');
857	      }
858	    }
859	    var out = buf.toString();
860	    if (out.isEmpty) {
861	      out = 'route';
862	    }
863	    const ext = '.gpx';
864	    final cap = maxChars - ext.length;
865	    if (out.length > cap) {
866	      out = out.substring(0, cap);
867	    }
868	    return '$out$ext';
869	  }
