1	import 'dart:math' as math;
2	
3	/// 骑行回放曲线的平滑工具：抹掉 GNSS 抖动和单采样离群值。
4	///
5	/// 放在 ride 层而不是画笔里，是因为这一层全是纯函数、能单测；
6	/// 画笔只负责画线，不该夹带数据清洗。所有函数都不修改入参。
7	abstract class RideSeriesSmooth {
8	  /// 权重核 [1,2,3,2,1]：中心权重略高，两端衰减，削毛刺但不压住平台。
9	  static const List<double> _kernel = <double>[1, 2, 3, 2, 1];
10	
11	  /// 核的单侧半径，与 [_kernel] 的长度一一对应。
12	  static const int _radius = 2;
13	
14	  /// Hampel 去尖峰：|v - median| > [sigmas] * 1.4826 * MAD 时替换为窗口
15	  /// median。[halfWindow] 是单侧窗口（窗口 = 2*halfWindow+1）。
16	  ///
17	  /// 用中位数而不是均值，尖峰本身就不会把判定基准带偏；1.4826 把 MAD
18	  /// 折算成正态分布下的标准差，[sigmas] 才能按「几倍标准差」理解。
19	  /// 所有替换都基于原始序列同时判定，避免前一个修补值污染后一个窗口。
20	  static List<double> despike(
21	    List<double> src, {
22	    int halfWindow = 2,
23	    double sigmas = 3.0,
24	  }) {
25	    final n = src.length;
26	    // 两点之间没有「邻域」可言，强行去尖峰只会把仅有的差异抹平。
27	    if (n <= 2) return List<double>.of(src);
28	    final half = math.max(0, halfWindow);
29	    final out = List<double>.of(src);
30	    for (var i = 0; i < n; i++) {
31	      final lo = math.max(0, i - half);
32	      final hi = math.min(n - 1, i + half);
33	      final window = src.sublist(lo, hi + 1)..sort();
34	      final median = _medianSorted(window);
35	      final devs = <double>[
36	        for (final v in window) (v - median).abs(),
37	      ]..sort();
38	      final limit = sigmas * 1.4826 * _medianSorted(devs);
39	      if ((src[i] - median).abs() > limit) out[i] = median;
40	    }
41	    return out;
42	  }
43	
44	  /// 加权滑动平均（核 [1,2,3,2,1]/9），边界自动缩短窗口，跑 [passes] 遍。
45	  ///
46	  /// 边界只取真实存在的邻点并重新归一化权值：补零会把端点朝 0 拽，
47	  /// 曲线首尾就会凭空多出一段下坠。多跑一遍是为了把单点毛刺摊得更开。
48	  static List<double> smooth(List<double> src, {int passes = 2}) {
49	    if (src.length <= 2) return List<double>.of(src);
50	    var cur = List<double>.of(src);
51	    for (var p = 0; p < math.max(0, passes); p++) {
52	      cur = _smoothOnce(cur);
53	    }
54	    return cur;
55	  }
56	
57	  static List<double> _smoothOnce(List<double> src) {
58	    final n = src.length;
59	    final out = List<double>.filled(n, 0);
60	    for (var i = 0; i < n; i++) {
61	      var sum = 0.0;
62	      var weight = 0.0;
63	      for (var k = 0; k < _kernel.length; k++) {
64	        final j = i + k - _radius;
65	        if (j < 0 || j >= n) continue;
66	        final w = _kernel[k];
67	        sum += src[j] * w;
68	        weight += w;
69	      }
70	      out[i] = sum / weight;
71	    }
72	    return out;
73	  }
74	
75	  /// 分桶平均降采样：每桶取均值，首尾样本原值保留，输出长度 ≤ [maxN]。
76	  ///
77	  /// 首尾各占一个单点桶：曲线必须从第一个真实样本起、落到最后一个真实
78	  /// 样本上，否则尾段会被吞掉，看起来像「回放没画完」。中间等分成
79	  /// maxN-2 个桶做均值，整数除法对齐边界，既不漏样本也不越界。
80	  static List<double> downsample(List<double> src, int maxN) {
81	    final n = src.length;
82	    if (n == 0 || maxN <= 0) return const [];
83	    if (n <= maxN) return List<double>.of(src);
84	    // 只有一个输出点时保不住两端，退化为首样本，至少不凭空造值。
85	    if (maxN == 1) return <double>[src.first];
86	    final out = List<double>.filled(maxN, 0);
87	    out[0] = src[0];
88	    out[maxN - 1] = src[n - 1];
89	    final buckets = maxN - 2;
90	    final inner = n - 2;
91	    for (var b = 0; b < buckets; b++) {
92	      final lo = 1 + (b * inner) ~/ buckets;
93	      final hi = 1 + ((b + 1) * inner) ~/ buckets;
94	      var sum = 0.0;
95	      for (var i = lo; i < hi; i++) {
96	        sum += src[i];
97	      }
98	      out[b + 1] = sum / (hi - lo);
99	    }
100	    return out;
101	  }
102	
103	  /// 组合：despike → smooth → downsample。
104	  ///
105	  /// 顺序有讲究：先摘掉孤立尖峰，否则平滑会把一个尖峰摊成一圈小鼓包；
106	  /// 最后再降采样，画笔每帧只需处理 [maxN] 个点（默认 160 够宽屏用）。
107	  ///
108	  /// 默认跑 3 遍平均：1 Hz 采样的速度序列做 2 遍时，峰谷之间残留的锯齿在
109	  /// 130 px 高的卡片里仍然像振动（实测肉眼可辨）；3 遍之后曲线才读得出趋势，
110	  /// 而真实的加减速段（几十个采样宽）不会被抹掉。
111	  static List<double> prepare(List<double> src, {int maxN = 160, int passes = 3}) {
112	    if (src.isEmpty) return const [];
113	    // 两个点连「平滑」都谈不上，保持原样最不容易出错。
114	    if (src.length <= 2) return List<double>.of(src);
115	    return downsample(smooth(despike(src), passes: passes), maxN);
116	  }
117	
118	  /// 已排序序列的中位数；偶数长度取中间两个的均值。
119	  static double _medianSorted(List<double> sorted) {
120	    final mid = sorted.length ~/ 2;
121	    if (sorted.length.isOdd) return sorted[mid];
122	    return (sorted[mid - 1] + sorted[mid]) / 2;
123	  }
124	}
