77	    required this.color,
78	    required this.fill,
79	    required this.avg,
80	    this.reveal = 1,
81	  });
82	
83	  final List<double> values;
84	  final Color color;
85	  final bool fill;
86	  final double? avg;
87	
88	  /// 0..1：只画到这一段宽度（进场揭示）。1 = 整条。
89	  final double reveal;
90	
91	  @override
92	  void paint(Canvas canvas, Size size) {
93	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
94	    const pad = EdgeInsets.fromLTRB(4, 10, 4, 6);
95	    final w = size.width - pad.left - pad.right;
96	    final h = size.height - pad.top - pad.bottom;
97	    if (w <= 0 || h <= 0) return;
98	
99	    var minV = values.reduce(math.min);
100	    var maxV = values.reduce(math.max);
101	    if (avg != null) {
102	      minV = math.min(minV, avg!);
103	      maxV = math.max(maxV, avg!);
104	    }
105	    if (maxV - minV < 0.2) {
106	      minV -= 1;
107	      maxV += 1;
108	    }
109	    final span = maxV - minV;
110	
111	    Offset pt(int i, double v) {
112	      final x = pad.left +
113	          (values.length == 1 ? w / 2 : w * i / (values.length - 1));
114	      final y = pad.top + h * (1 - (v - minV) / span);
115	      return Offset(x, y);
116	    }
117	
118	    final pts = [for (var i = 0; i < values.length; i++) pt(i, values[i])];
119	    final line = monotonePath(pts);
120	
121	    final r = reveal.clamp(0.0, 1.0);
122	    final revealed = r < 1;
123	    if (revealed) {
124	      canvas.save();
125	      canvas.clipRect(Rect.fromLTWH(0, 0, size.width * r, size.height));
126	    }
127	
128	    if (fill) {
129	      final area = Path.from(line)
130	        ..lineTo(pts.last.dx, pad.top + h)
131	        ..lineTo(pts.first.dx, pad.top + h)
132	        ..close();
133	      canvas.drawPath(
134	        area,
135	        Paint()
136	          ..shader = LinearGradient(
137	            begin: Alignment.topCenter,
138	            end: Alignment.bottomCenter,
139	            colors: [
140	              color.withValues(alpha: 0.42),
141	              color.withValues(alpha: 0.02),
142	            ],
143	          ).createShader(Offset.zero & size),
144	      );
145	    }
146	
147	    canvas.drawPath(
148	      line,
149	      Paint()
150	        ..color = color
151	        ..style = PaintingStyle.stroke
152	        ..strokeWidth = 2.2
153	        ..strokeJoin = StrokeJoin.round
154	        ..strokeCap = StrokeCap.round,
155	    );
156	
157	    final a = avg;
158	    if (a != null) {
159	      final y = pt(0, a).dy;
160	      _dash(
161	        canvas,
162	        Offset(pad.left, y),
163	        Offset(pad.left + w, y),
164	        Paint()
165	          ..color = color.withValues(alpha: 0.7)
166	          ..strokeWidth = 1.2,
167	      );
168	    }
169	
170	    if (revealed) canvas.restore();
171	  }
172	
173	  /// 单调三次曲线（Fritsch–Carlson）：相邻两点之间用 Bézier 连接，切线在
174	  /// 局部极值处置 0，所以平滑之后**不会在极值附近过冲** —— 普通 Catmull-Rom
175	  /// 会把尖峰画成一个超出数据范围的鼓包，读数就成了假的。
176	  static Path monotonePath(List<Offset> p) {
177	    final path = Path();
178	    if (p.isEmpty) return path;
179	    path.moveTo(p.first.dx, p.first.dy);
180	    final n = p.length;
181	    if (n == 1) return path;
182	    if (n == 2) {
183	      path.lineTo(p[1].dx, p[1].dy);
184	      return path;
185	    }
186	    final d = List<double>.filled(n - 1, 0);
187	    for (var i = 0; i < n - 1; i++) {
188	      final dx = p[i + 1].dx - p[i].dx;
189	      d[i] = dx.abs() < 1e-6 ? 0 : (p[i + 1].dy - p[i].dy) / dx;
190	    }
191	    final m = List<double>.filled(n, 0);
192	    for (var i = 1; i < n - 1; i++) {
193	      // 极值点切线取 0：曲线在峰顶是平的，不会冲过头。
194	      m[i] = d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2;
195	    }
196	    m[0] = d.first;
197	    m[n - 1] = d.last;
198	    for (var i = 0; i < n - 1; i++) {
199	      if (d[i] == 0) {
200	        m[i] = 0;
201	        m[i + 1] = 0;
202	        continue;
203	      }
204	      final a = m[i] / d[i];
205	      final b = m[i + 1] / d[i];
206	      final s = a * a + b * b;
207	      if (s > 9) {
208	        final t = 3 / math.sqrt(s);
209	        m[i] = t * a * d[i];
210	        m[i + 1] = t * b * d[i];
211	      }
212	    }
213	    for (var i = 0; i < n - 1; i++) {
214	      final dx = p[i + 1].dx - p[i].dx;
215	      path.cubicTo(
216	        p[i].dx + dx / 3,
217	        p[i].dy + m[i] * dx / 3,
218	        p[i + 1].dx - dx / 3,
219	        p[i + 1].dy - m[i + 1] * dx / 3,
220	        p[i + 1].dx,
221	        p[i + 1].dy,
222	      );
223	    }
224	    return path;
225	  }
226	
227	  static void _dash(Canvas canvas, Offset a, Offset b, Paint paint) {
228	    const dash = 5.0;
229	    const gap = 4.0;
230	    final len = (b - a).distance;
231	    if (len < 1) return;
232	    final dir = (b - a) / len;
233	    var t = 0.0;
234	    while (t < len) {
235	      final end = math.min(t + dash, len);
236	      canvas.drawLine(a + dir * t, a + dir * end, paint);
237	      t += dash + gap;
238	    }
239	  }
240	
241	  @override
242	  bool shouldRepaint(covariant _SeriesPainter old) =>
243	      old.values != values ||
244	      old.color != color ||
245	      old.fill != fill ||
246	      old.avg != avg ||
247	      old.reveal != reveal;
248	}
