303	class _BarPainter extends CustomPainter {
304	  _BarPainter({
305	    required this.values,
306	    required this.labels,
307	    required this.color,
308	    required this.avg,
309	    required this.avgText,
310	    required this.highlight,
311	  });
312	
313	  final List<double> values;
314	  final List<String> labels;
315	  final Color color;
316	  final double? avg;
317	  final String? avgText;
318	  final int highlight;
319	
320	  static const _emptyBar = Color(0xFF3A3A3C);
321	  static const _labelColor = Color(0xFF8E8E93);
322	
323	  @override
324	  void paint(Canvas canvas, Size size) {
325	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
326	    final w = size.width;
327	    // 有标签才留那一行；迷你图（labels 全空）就贴边画，别浪费高度。
328	    final hasLabel = labels.any((l) => l.isNotEmpty);
329	    final padTop = hasLabel ? 10.0 : 3.0;
330	    final padBottom = hasLabel ? 17.0 : 3.0;
331	    final h = size.height - padTop - padBottom;
332	    if (h <= 0) return;
333	
334	    final maxV = values.fold<double>(0, math.max);
335	    final scaleMax = math.max(maxV, avg ?? 0) * 1.12;
336	    final slot = w / values.length;
337	    final barW = math.min(slot * 0.62, 18.0);
338	
339	    for (var i = 0; i < values.length; i++) {
340	      final v = values[i];
341	      final cx = slot * (i + 0.5);
342	      final frac = scaleMax <= 0 ? 0.0 : (v / scaleMax).clamp(0.0, 1.0);
343	      // 0 也留 2 px 灰底：能看出「这一天存在、只是没骑」。
344	      final barH = frac <= 0 ? 2.0 : math.max(2.0, h * frac);
345	      final isHi = i == highlight;
346	
347	      canvas.drawRRect(
348	        RRect.fromRectAndRadius(
349	          Rect.fromLTWH(cx - barW / 2, padTop + h - barH, barW, barH),
350	          Radius.circular(math.min(barW / 2, 3)),
351	        ),
352	        Paint()
353	          ..color = v <= 0
354	              ? _emptyBar
355	              : (isHi ? color : color.withValues(alpha: 0.55)),
356	      );
357	
358	      final label = i < labels.length ? labels[i] : '';
359	      if (label.isEmpty) continue;
360	      final tp = TextPainter(
361	        text: TextSpan(
362	          text: label,
363	          style: TextStyle(
364	            color: isHi ? Colors.white : _labelColor,
365	            fontSize: 10,
366	            fontWeight: isHi ? FontWeight.w700 : FontWeight.w400,
367	          ),
368	        ),
369	        textDirection: TextDirection.ltr,
370	      )..layout();
371	      tp.paint(canvas, Offset(cx - tp.width / 2, size.height - padBottom + 4));
372	    }
373	
374	    final a = avg;
375	    if (a != null && a > 0) {
376	      final y = padTop + h * (1 - (a / scaleMax).clamp(0.0, 1.0));
377	      final paint = Paint()
378	        ..color = color.withValues(alpha: 0.85)
379	        ..strokeWidth = 1.4;
380	      _SeriesPainter._dash(canvas, Offset(0, y), Offset(w, y), paint);
381	
382	      // 数值标签贴在线右端上方：只有一条线看不出它落在哪一档。
383	      final text = avgText;
384	      if (text != null && text.isNotEmpty) {
385	        final tp = TextPainter(
386	          text: TextSpan(
387	            text: text,
388	            style: TextStyle(
389	              color: color,
390	              fontSize: 9,
391	              fontWeight: FontWeight.w700,
392	            ),
393	          ),
394	          textDirection: TextDirection.ltr,
395	        )..layout();
396	        tp.paint(canvas, Offset(w - tp.width, y - tp.height - 2));
397	      }
398	    }
399	  }
400	
401	  @override
402	  bool shouldRepaint(covariant _BarPainter old) =>
403	      old.values != values ||
404	      old.labels != labels ||
405	      old.color != color ||
406	      old.avg != avg ||
407	      old.avgText != avgText ||
408	      old.highlight != highlight;
409	}
