437	class _PacePainter extends CustomPainter {
438	  _PacePainter({required this.speeds, this.range});
439	
440	  final List<double> speeds;
441	  final ({double lo, double hi})? range;
442	
443	  @override
444	  void paint(Canvas canvas, Size size) {
445	    final r = RRect.fromRectAndRadius(
446	      Offset.zero & size,
447	      const Radius.circular(5),
448	    );
449	    canvas.save();
450	    canvas.clipRRect(r);
451	    if (speeds.length < 2) {
452	      canvas.drawRRect(
453	        r,
454	        Paint()
455	          ..shader = const LinearGradient(
456	            colors: [
457	              RideTrackStyle.bandSlow,
458	              RideTrackStyle.bandMid,
459	              RideTrackStyle.bandFast,
460	            ],
461	          ).createShader(Offset.zero & size),
462	      );
463	    } else {
464	      final minV = range?.lo ?? speeds.reduce(math.min);
465	      final maxV = range?.hi ?? speeds.reduce(math.max);
466	      final w = size.width / speeds.length;
467	      for (var i = 0; i < speeds.length; i++) {
468	        // 与轨迹线共用同一个映射（[RideTrackStyle.speedBandColor]），颜色才对得上。
469	        canvas.drawRect(
470	          Rect.fromLTWH(i * w, 0, w + 0.6, size.height),
471	          Paint()..color = RideTrackStyle.speedBandColor(speeds[i], minV, maxV),
472	        );
473	      }
474	    }
475	    canvas.restore();
476	  }
477	
478	  @override
479	  bool shouldRepaint(covariant _PacePainter old) =>
480	      old.speeds != speeds || old.range != range;
481	}
