208	  /// 当前画到的小数下标（4.5 表示在第 4、5 点之间）。
209	  double get _playCut {
210	    if (_disp.length < 2) return 0;
211	    // 没有速度信息 → 没有时间轴，按点数均匀播。
212	    if (_rideT.length != _disp.length || _rideTotal <= 0) {
213	      return _play.value * (_disp.length - 1);
214	    }
215	    final sec = _play.value * _rideTotal;
216	    // 播完就整条。二进制查找找的是「第一个 >= sec 的下标」，如果尾部有一串
217	    // 零位移点（原地停留，累计时间相同）会停在那串的第一个上，线就画不到底、
218	    // 游标也不消失。
219	    if (sec >= _rideTotal) return _disp.length - 1;
220	    var lo = 0;
221	    var hi = _rideT.length - 1;
222	    while (lo < hi) {
223	      final mid = (lo + hi) >> 1;
224	      if (_rideT[mid] < sec) {
225	        lo = mid + 1;
226	      } else {
227	        hi = mid;
228	      }
229	    }
230	    final i = lo < 1 ? 1 : lo;
231	    final t0 = _rideT[i - 1];
232	    final t1 = _rideT[i];
233	    final f = t1 - t0 <= 0 ? 1.0 : ((sec - t0) / (t1 - t0)).clamp(0.0, 1.0);
234	    return (i - 1) + f;
235	  }
