253	  void _onSheetDragUpdate(double dy, double bodyH) {
254	    final travel = bodyH * 0.5 - _peekBody;
255	    if (travel <= 8) return;
256	    if (_sheet.isAnimating) _sheet.stop();
257	    _sheet.value = (_sheet.value - dy / travel).clamp(0.0, 1.0);
258	  }
259	
260	  void _onSheetDragEnd(double velocity) {
261	    final next = velocity < -350
262	        ? 1.0
263	        : velocity > 350
264	            ? 0.0
265	            : _sheet.value >= 0.45
266	                ? 1.0
267	                : 0.0;
268	    _sheet.animateTo(next, curve: Curves.easeOutCubic);
269	  }
