271	  CameraFit? _fitOf(List<LatLng> pts, {EdgeInsets padding = _mapPad}) {
272	    if (pts.length < 2) return null;
273	    return CameraFit.bounds(
274	      bounds: LatLngBounds.fromPoints(pts),
275	      padding: padding,
276	      maxZoom: 16,
277	      minZoom: 3,
278	      forceIntegerZoomLevel: true,
279	    );
280	  }
