282	  /// 用控件真实尺寸算出第一帧相机，避免先对着起点再跳到整条轨迹。
283	  ///
284	  /// 结果按 [padding] 缓存：只在 FlutterMap 首次 build 时生效，之后控件重建、
285	  /// 抽屉拖动都不会用到它，重算等于每帧白跑一遍整条轨迹的投影。
286	  ({LatLng center, double zoom})? _cameraFor(
287	    List<LatLng> pts,
288	    Size size, {
289	    EdgeInsets padding = _mapPad,
290	  }) {
291	    final cached = _camCache[padding];
292	    if (cached != null) return cached;
293	    final fit = _fitOf(pts, padding: padding);
294	    if (fit == null || size.width < 8 || size.height < 8) return null;
295	    try {
296	      final fitted = fit.fit(
297	        MapCamera(
298	          crs: const Epsg3857(),
299	          center: pts.first,
300	          zoom: 10,
301	          rotation: 0,
302	          nonRotatedSize: size,
303	          minZoom: 3,
304	          maxZoom: 18,
305	        ),
306	      );
307	      final cam = (center: fitted.center, zoom: fitted.zoom);
308	      _camCache[padding] = cam;
309	      return cam;
310	    } catch (_) {
311	      return null;
312	    }
313	  }
