591	  /// [playable] 为 true 时地图跟着回放进度重建（只有详情页的主地图要）。
592	  Widget _mapView(
593	    MapController controller, {
594	    EdgeInsets fitPad = _mapPad,
595	    bool playable = false,
596	  }) {
597	    if (_disp.isEmpty) {
598	      return const ColoredBox(
599	        color: Color(0xFFEDE8DF),
600	        child: Center(
601	          child: Icon(Icons.map_outlined, color: AppTheme.muted, size: 48),
602	        ),
603	      );
604	    }
605	    Widget build({required double? cut}) => LayoutBuilder(
606	      builder: (context, box) {
607	        final mapSize = Size(box.maxWidth, box.maxHeight);
608	        if (mapSize.width < 8 || mapSize.height < 8) {
609	          return const ColoredBox(color: Color(0xFFEDE8DF));
610	        }
611	        final cam = _cameraFor(_disp, mapSize, padding: fitPad);
612	        // 单独一层：抽屉拖动 / 底栏刷新不会把地图的栅格一起标脏。
613	        return RepaintBoundary(
614	          child: FlutterMap(
615	            mapController: controller,
616	            options: MapOptions(
617	              initialCenter: cam?.center ?? _disp.first,
618	              initialZoom: cam?.zoom ?? 14,
619	              minZoom: 3,
620	              maxZoom: 18,
621	              interactionOptions: const InteractionOptions(
622	                flags: InteractiveFlag.all & ~InteractiveFlag.rotate,
623	              ),
624	              backgroundColor: const Color(0xFFEDE8DF),
625	            ),
626	            children: [
627	              HelmOsmTiles.layer(
628	                tileDisplay: const TileDisplay.instantaneous(),
629	              ),
630	              ...rideTrackLayers(
631	                display: _disp,
632	                summary: _sum,
633	                wgs: _pts,
634	                stops: _stops,
635	                cut: cut,
636	                kmMarks: _kmMarks,
637	              ),
638	            ],
639	          ),
640	        );
641	      },
642	    );
643	
644	    // 分享封面用完整轨迹，不参与回放。
645	    if (!playable) return build(cut: null);
646	    // 只让地图这一层跟着回放重建：整页 60 fps 重建会把面板和榜单一起带上。
647	    return ListenableBuilder(
648	      listenable: _play,
649	      builder: (context, _) => build(cut: _playCut),
650	    );
651	  }
