849	/// 抽屉里的卡片错峰入场：展开时逐张上浮淡入。
850	///
851	/// 用 `Interval` 在一条 Tween 里做出延迟，不额外起 Timer / Controller；
852	/// 抽屉收起时 ListView 整体销毁，再展开自然重播一次。
853	class _Reveal extends StatelessWidget {
854	  const _Reveal({required this.index, required this.child});
855	
856	  final int index;
857	  final Widget child;
858	
859	  @override
860	  Widget build(BuildContext context) {
861	    return TweenAnimationBuilder<double>(
862	      tween: Tween<double>(begin: 0, end: 1),
863	      duration: const Duration(milliseconds: 560),
864	      curve: Interval(
865	        (index * 0.08).clamp(0.0, 0.5),
866	        1,
867	        curve: Curves.easeOutCubic,
868	      ),
869	      builder: (context, t, child) => Opacity(
870	        opacity: t,
871	        child: Transform.translate(offset: Offset(0, 12 * (1 - t)), child: child),
872	      ),
873	      child: child,
874	    );
875	  }
876	}
